export function validateOlympic(input={}){const f={...olympicDefaults,...input};function finite(x){if(typeof x==='number'&&!Number.isFinite(x))throw Error('Olympic values must be finite');if(x&&typeof x==='object')Object.values(x).forEach(finite);}for(const[k,v]of Object.entries(input))if(k.startsWith('olympic'))finite(v);for(const k of ['olympicSceneDurations','olympicLayerEdits','olympicSourceBindings','olympicFullSources'])if(!f[k]||typeof f[k]!=='object'||Array.isArray(f[k]))throw Error('Use an object: '+k);if(f.olympicTitleSettle<=0||f.olympicLetterStagger<0||f.olympicTitleSize<=0||f.olympicParticleCount<0||f.olympicParticleCount>250||f.olympicParticleSpeed<0)throw Error('Invalid glyph/particle size or timing');if(f.olympicRate<.05||f.olympicRate>4)throw Error('Sequence rate must be 0.05–4');for(const[k,v]of Object.entries(olympicDefaults))if(typeof v==='number'&&!Number.isFinite(f[k]))throw Error('Finite parameter required: '+k);for(const[id,v]of Object.entries(f.olympicSceneDurations)){if(!olympicStages.some(s=>s.id===id)||!Number.isFinite(v)||v<.05||v>300)throw Error('Invalid scene duration: '+id);}for(const[id,e]of Object.entries(f.olympicLayerEdits)){if(!e||typeof e!=='object'||Array.isArray(e))throw Error('Use layer object '+id);for(const k of ['x','y','scale','rotation','opacity','depth','blur','brightness'])if(e[k]!==undefined&&(!Number.isFinite(e[k])||['scale','depth'].includes(k)&&e[k]<=0||k==='opacity'&&(e[k]<0||e[k]>1)))throw Error('Invalid transform '+id+'.'+k);sampleObjectMotion(0,e.motion||{});}if(!Array.isArray(f.olympicEyePoints)||f.olympicEyePoints.length!==2||f.olympicEyePoints.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isFinite(n)||n<0||n>1)))throw Error('Two normalized eye points required');for(const k of ['olympicTitle','olympicDate'])if(typeof f[k]!=='string'||f[k].length>120)throw Error('Invalid text: '+k);return f;}
