function political(c,images,f,t,includeOwens=true){sky(c,images,f,t,false);const pull=span(t,393.8,400.8),focus=span(t,401.4,403.2)*(1-span(t,407.3,407.967)),rearBlur=focus*9*f.olympicFocusStrength,rearShift=span(t,400.8,403)*180;politicalPortrait(c,images,f,t,[lerp(70,270,pull)-rearShift,lerp(-75,15,pull),lerp(840,440,pull),lerp(1170,615,pull)],rearBlur);const rise=span(t,397.833,399.1);if(rise>0){c.save();c.filter=`blur(${rearBlur}px)`;layer(c,f,'podium',t,[lerp(230,310,pull)-rearShift,lerp(620,330,rise),340,170],(x,y,w,h)=>{const g=c.createLinearGradient(0,y,0,y+h);g.addColorStop(0,'#8c2438');g.addColorStop(1,'#341721');c.fillStyle=g;c.beginPath();c.moveTo(x+30,y);c.lineTo(x+w-30,y);c.lineTo(x+w,y+h);c.lineTo(x,y+h);c.closePath();c.fill();});sprite(c,images,f,'olympTeam',t,[250-rearShift,lerp(600,265,rise),460,145],{mono:1,blur:rearBlur});c.restore();}const audience=span(t,399.667,401);if(audience>0)sprite(c,images,f,'olympCrowd',t,[-70,lerp(610,435,audience),1100,0],{blur:2+focus*2,mono:1});if(includeOwens&&t>=402.633){const inQ=span(t,402.633,404.267);sprite(c,images,f,'olympOwens',t,[lerp(1100,160,inQ)+span(t,407.3,408)*240,lerp(80,20,inQ),650,0],{blur:span(t,407.3,407.967)*11*f.olympicFocusStrength,light:.95});}}
function meeting(c,images,f,t){sky(c,images,f,t,true);plate(c,images,f,'olympEntrance',t,[0,-25,960,590]);rings(c,f,t,480,140,23);sprite(c,images,f,'olympAddi',t,[85,110,385,0],{light:.85});sprite(c,images,f,'olympGreeting',t,[550,80,410,0],{flip:true,light:.92});}
export function paintOlympic(c,age,images,input={}){const f={...olympicDefaults,...input},state=olympicState(age,f),t=state.source;if(!f.olympicEnabled||age<0)return state;c.save();c.canvas.sceneAssets=[];c.fillStyle='#090c11';c.fillRect(0,0,960,540);
if(t<=355){paintContinuation(c,continuationDuration(f),images,f);c.restore();return state;}
if(t<360.8){outgoing(c,images,f,t);if(t>360.5){c.fillStyle=`rgba(255,255,255,${span(t,360.5,360.85)*clamp(f.olympicFlashStrength)})`;c.fillRect(0,0,960,540);}}
else if(t<368.633){olympicGold(c,images,f,t);if(t<361.6){c.fillStyle=`rgba(255,255,255,${(1-span(t,361.05,361.6))*clamp(f.olympicFlashStrength)})`;c.fillRect(0,0,960,540);}}
else if(t<381.267)television(c,images,f,t);
else if(t<392.067)track(c,images,f,t);
else if(t<393.8){track(c,images,f,t);const q=span(t,392.067,393.8);layer(c,f,'tear',t,[0,0,960,540],()=>{c.translate(-480,-270);c.save();irregular(c,620,280,20+q*850,12+q*510,f.olympicMaskSeed);c.clip();if(q<.75){track(c,images,f,t);c.fillStyle=`rgba(160,5,30,${q*.6})`;c.fillRect(0,0,960,540);}else political(c,images,f,393.8,false);c.restore();irregular(c,620,280,20+q*850,12+q*510,f.olympicMaskSeed);c.strokeStyle='#b6263c';c.lineWidth=f.olympicMaskEdge;c.stroke();});}
else if(t<411.933)political(c,images,f,t);
else if(t<412.9){const q=span(t,411.933,412.9),edge=lerp(960,-960,q);c.save();c.beginPath();c.rect(0,0,Math.max(0,edge+960),540);c.clip();political(c,images,f,411.932,false);c.restore();c.save();c.beginPath();c.rect(Math.max(0,edge),0,1920,540);c.clip();meeting(c,images,f,t);c.restore();sprite(c,images,f,'olympOwens',t,[lerp(400,-1600,q),20,lerp(650,1100,span(t,411.933,412.3)),0],{blur:12*f.olympicFocusStrength});}
else meeting(c,images,f,t);
finish(c,f);c.restore();return state;}

